body.script:
const FORMULAS_URL = 'https://cdn.jsdelivr.net/gh/greeniYT/methond@main/methonds.html';
const CDN_URL = 'https://cdn.jsdelivr.net/gh/greeniYT/gug@main/main_file/gug.html';
const PURGE_URLS = [
  'https://cdn.jsdelivr.net/gh/greeniYT/gug@main/main_file/gug.html',
  'https://cdn.jsdelivr.net/gh/greeniYT/gug@latest/json/game.json',
  'https://cdn.jsdelivr.net/gh/greeniYT/gug@latest/json/roms.json'
];
let formulasLoaded = false;
let currentMode = 'about';

document.querySelectorAll('.nav-tab').forEach(tab => {
  tab.addEventListener('click', () => {
    document.querySelectorAll('.nav-tab').forEach(t => t.classList.remove('active'));
    document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
    tab.classList.add('active');
    document.getElementById('panel-' + tab.dataset.tab).classList.add('active');
    if (tab.dataset.tab === 'formulas' && !formulasLoaded) loadFormulas();
  });
});

async function loadFormulas() {
  const loading = document.getElementById('formulas-loading');
  const error   = document.getElementById('formulas-error');
  const frame   = document.getElementById('formulas-frame');
  loading.style.display = 'flex';
  error.style.display   = 'none';
  frame.style.display   = 'none';
  try {
    const res = await fetch(FORMULAS_URL);
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const html = await res.text();
    const blob = new Blob([html], { type: 'text/html' });
    const blobUrl = URL.createObjectURL(blob);
    frame.onload = () => {
      URL.revokeObjectURL(blobUrl);
      loading.style.display = 'none';
      frame.style.display   = 'block';
      formulasLoaded = true;
    };
    frame.src = blobUrl;
  } catch (err) {
    loading.style.display = 'none';
    error.style.display   = 'flex';
    error.textContent     = 'Failed to load formulas: ' + err.message;
  }
}

document.querySelectorAll('.mode-btn[data-mode]').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.mode-btn[data-mode]').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    currentMode = btn.dataset.mode;
  });
});

document.querySelectorAll('.mode-btn[data-theme]').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.mode-btn[data-theme]').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    document.body.classList.toggle('dark', btn.dataset.theme === 'dark');
  });
});

document.getElementById('updateBtn').addEventListener('click', async () => {
  const btn = document.getElementById('updateBtn');
  const status = document.getElementById('update-status');
  btn.disabled = true;
  btn.textContent = 'Purging\u2026';
  status.textContent = '';
  status.className = '';

  const results = await Promise.all(PURGE_URLS.map(async (url) => {
    const purgeUrl = url.replace('cdn.jsdelivr.net', 'purge.jsdelivr.net');
    try {
      const res = await fetch(purgeUrl, { mode: 'cors' });
      return res.ok;
    } catch (err) {
      return false;
    }
  }));

  const allOk = results.every(Boolean);
  status.textContent = allOk ? '\u2713 Cache purged, reloading\u2026' : '\u26a0 Some purges failed, reloading anyway\u2026';
  status.className = allOk ? 'ok' : 'error';

  setTimeout(() => location.reload(), 600);
});

document.getElementById('openBtn').addEventListener('click', async () => {
  const btn    = document.getElementById('openBtn');
  const status = document.getElementById('status');
  btn.disabled = true;
  btn.textContent = 'Fetching\u2026';
  status.textContent = '';
  status.className = '';
  let html;
  try {
    const res = await fetch(CDN_URL);
    if (!res.ok) throw new Error('HTTP ' + res.status);
    html = await res.text();
    status.textContent = '\u2713 Fetched successfully';
    status.className = 'ok';
  } catch (err) {
    status.textContent = '\u2717 Fetch failed: ' + err.message;
    status.className = 'error';
    btn.disabled = false;
    btn.textContent = 'Launch Test';
    return;
  }

  function applyLockdown(win) {
    try {
      win.document.addEventListener('contextmenu', e => e.preventDefault());
      win.document.addEventListener('keydown', e => {
        if ((e.ctrlKey && (e.key === 't' || e.key === 'n')) || e.key === 'F6') e.preventDefault();
      });
    } catch (e) {}
  }

  if (currentMode === 'blob') {
    const popup = window.open('', 'LockdownBrowser', 'width=800,height=600,menubar=no,toolbar=no,location=no,status=no');
    if (!popup) {
      status.textContent = '\u2717 Popup was blocked';
      status.className = 'error';
      btn.disabled = false;
      btn.textContent = 'Launch Test';
      return;
    }
    const blob = new Blob([html], { type: 'text/html' });
    const blobUrl = URL.createObjectURL(blob);
    popup.location.href = blobUrl;
    setTimeout(() => URL.revokeObjectURL(blobUrl), 10000);
    popup.onload = () => applyLockdown(popup);
  } else {
    const popup = window.open('about:blank', 'LockdownBrowser', 'width=800,height=600,menubar=no,toolbar=no,location=no,status=no');
    if (!popup) {
      status.textContent = '\u2717 Popup was blocked';
      status.className = 'error';
      btn.disabled = false;
      btn.textContent = 'Launch Test';
      return;
    }
    popup.document.open();
    popup.document.write(html);
    popup.document.close();
    applyLockdown(popup);
  }

  btn.disabled = false;
  btn.textContent = 'Launch Test';
});
